import"./chunk-2NFLSA4Y.js";var a={thermal:{variable:{alpha:"Linear expansion coefficient (1/K)"},material:{steel:"Steel",aluminium:"Aluminium",copper:"Copper",brass:"Brass",invar:"Invar"},ballRing:{param:{ballTarget:"Ball: target temperature",ringTarget:"Ring: target temperature",ballMaterial:"Ball material",ringMaterial:"Ring material",clearance:"Initial diameter clearance",timeStep:"Time step"},hint:{ballTarget:"Heat the ball to make it larger; cool it back to room temperature to make it fit again.",ringTarget:"Heating the ring also enlarges its hole. Try heating both bodies to the same temperature.",clearance:"Hole diameter minus ball diameter at 20 \xB0C. A small clearance makes thermal expansion easy to detect."},preset:{room:"Room temperature",hot:"Heat to 200 \xB0C"},measure:{ballTemp:"Ball temperature",ringTemp:"Ring temperature",ballDiameter:"Ball diameter",holeDiameter:"Hole diameter",clearance:"Diameter clearance",ballExpansion:"Ball diameter increase",holeExpansion:"Hole diameter increase"},graph:{temperatures:"Ball and ring temperatures",clearance:"Does the ball fit?"},theory:{concept:"[[Thermal expansion is the increase in the size of a body \u2014 its length, area and volume \u2014 when it is heated.]] When the body cools, it contracts again. The particles of a heated body vibrate more strongly and move a little further apart, so the whole body grows. The change is small, but it can decide whether a ball fits through a ring."},section:{experiment:{title:"Predict, heat, test",text:"First watch the ball pass at room temperature. [[Then heat only the ball to 200 \xB0C and wait for the next test.]] Finally heat the ring too. The suspension lowers and lifts the ball automatically; it does not fall freely."},hole:{title:"Does a hole expand too?",text:"Yes. Imagine filling the hole with the same metal. On heating, every length grows, including the diameter of that imagined disk. [[The empty hole therefore gets larger too, as long as the ring can expand freely.]]"},materials:{title:"Different metals, different expansion",text:"[[The change depends on the expansion coefficient \u03B1, the initial size and the temperature change.]] Aluminium expands more than steel for the same temperature change; Invar expands very little. Try an aluminium ball and an Invar ring."},everyday:{title:"Expansion in technology and everyday life",text:"[[Engineers always leave room for expansion: bridges have expansion joints, gaps are left between rails, and long pipes get U-shaped bends.]] A 10 m steel rail grows by only about 1.2 mm for every 10 \xB0C, but if it cannot expand it pushes with an enormous force and can buckle. Power lines sag lower in summer. A bimetallic strip \u2014 two metals with different \u03B1 joined together \u2014 bends when heated and switches thermostats in irons and kettles on and off."},liquids:{title:"Liquids and gases",text:"Liquids usually expand more than solids \u2014 a liquid thermometer works this way \u2014 and gases expand the most (see \u201CGas laws\u201D). [[Water is an exception: between 0 \xB0C and 4 \xB0C it contracts when heated, so it is densest at 4 \xB0C.]] That is why lakes freeze from the top and fish survive the winter in the water below."}},formula:{diameter:"Thermal expansion of a diameter",clearance:"The ball fits when the hole is wider"},variable:{d0:"Diameter at the reference temperature",t0:"Reference temperature (20 \xB0C)"},assumption:{alpha:"The metals expand equally in every direction; their expansion coefficients are treated as constant.",uniform:"Each body has a uniform temperature and approaches its own target independently. Heat exchange between bodies is neglected; heating and cooling are accelerated.",motion:"A motor prescribes the vertical motion. The ring is a thin cylindrical opening; contact is rigid, without deformation, friction or calculated contact forces. The supports do not restrict expansion.",drawing:"Size differences relative to the original ball diameter are magnified \xD740. The stand and motion are illustrative, not to scale. Readings show actual dimensions."},view:{ball:"Ball",ring:"Ring",blocked:"Stopped by the ring",passed:"Passed through",fits:"The ball fits",tooLarge:"The ball is too large",note:"Size differences \xD740 \xB7 automatic fit test every 8 s"},challenge:{cold:{title:"The first pass",description:"Let the ball pass through the ring with both bodies below 30 \xB0C.",hint:"Set both target temperatures to 20 \xB0C and watch a full cycle."},block:{title:"Stop the ball with heat",description:"Keep the ring cool and heat the ball above 150 \xB0C until the ring stops it.",hint:"Set the ball to 200 \xB0C and the ring to 20 \xB0C. Wait for the next lowering."},ring:{title:"Make room for the hot ball",description:"Get the ball through with both bodies hotter than 180 \xB0C.",hint:"Heat both to 200 \xB0C. The hole expands too!"},metals:{title:"Same temperature, different result",description:"Use different metals and stop the ball even when both bodies are above 180 \xB0C at almost the same temperature.",hint:"Try an aluminium ball and an Invar ring at 300 \xB0C."}}}}},i={sim:a};export{i as default,a as sim};
